<?php
require '../config/app.php'; require_role(['admin','staff']); $title='Patient Record'; $basePath='../'; $id=(int)($_GET['id']??0);
$st=$pdo->prepare("SELECT id,name,email,phone,created_at FROM users WHERE id=? AND role='patient'");$st->execute([$id]);$patient=$st->fetch();if(!$patient)exit('Patient not found.');
$st=$pdo->prepare("SELECT a.*,t.name test_name,t.category,t.price,p.status payment_status,p.method,p.transaction_id,p.paid_at,te.name technician_name,r.sample_status,r.result_status,r.result_text,rep.id report_id,rep.report_title,rep.report_content,rep.created_at report_created FROM appointments a JOIN diagnostic_tests t ON t.id=a.test_id LEFT JOIN payments p ON p.appointment_id=a.id LEFT JOIN users te ON te.id=a.technician_id LEFT JOIN test_results r ON r.appointment_id=a.id LEFT JOIN reports rep ON rep.appointment_id=a.id WHERE a.patient_id=? ORDER BY a.appointment_date DESC,a.appointment_time DESC");$st->execute([$id]);$rows=$st->fetchAll();
require '../partials/header.php'; ?>
<div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><span class="text-primary fw-semibold">ADMIN · PATIENT RECORD</span><h2 class="dashboard-title mt-1 mb-0"><?=e($patient['name'])?></h2><p class="text-muted mb-0">Complete appointment, test, payment and report history.</p></div><a href="patients.php" class="btn btn-light">Back to patients</a></div>
<div class="row g-4 mb-4"><div class="col-lg-4"><div class="card p-4 h-100"><div class="profile-avatar mb-3"><?=strtoupper(substr($patient['name'],0,1))?></div><h4><?=e($patient['name'])?></h4><div class="profile-list mt-3"><div><i class="bi bi-envelope"></i><?=e($patient['email'])?></div><div><i class="bi bi-telephone"></i><?=e($patient['phone']?:'Not provided')?></div><div><i class="bi bi-calendar3"></i>Joined <?=e(date('d M Y',strtotime($patient['created_at'])))?></div></div></div></div><div class="col-lg-8"><div class="card p-4 h-100"><h5>Patient summary</h5><div class="row g-3 mt-1"><div class="col-6 col-md-3"><div class="stat-card bg-light rounded-4"><small>Appointments</small><h3><?=count($rows)?></h3></div></div><div class="col-6 col-md-3"><div class="stat-card bg-light rounded-4"><small>Completed</small><h3><?=count(array_filter($rows,fn($r)=>$r['status']==='Completed'))?></h3></div></div><div class="col-6 col-md-3"><div class="stat-card bg-light rounded-4"><small>Reports</small><h3><?=count(array_filter($rows,fn($r)=>!empty($r['report_id'])))?></h3></div></div><div class="col-6 col-md-3"><div class="stat-card bg-light rounded-4"><small>Paid</small><h3><?=money(array_sum(array_map(fn($r)=>$r['payment_status']==='Paid'?(float)$r['price']:0,$rows)))?></h3></div></div></div></div></div></div>
<div class="card table-card p-3"><div class="d-flex justify-content-between align-items-center mb-3"><div><h5>Test & report history</h5><p class="text-muted small mb-0">Admin can review every patient's test and report from one place.</p></div></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Test</th><th>Appointment</th><th>Technician</th><th>Payment</th><th>Result</th><th>Report</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['test_name'])?></strong><div class="small text-muted"><?=e($r['category'])?></div></td><td><?=e($r['appointment_date'])?><br><small><?=date('h:i A',strtotime($r['appointment_time']))?></small><br><span class="badge text-bg-light"><?=e($r['status'])?></span></td><td><?=e($r['technician_name']??'Unassigned')?></td><td><?=e($r['payment_status']??'Pending')?><br><small class="text-muted"><?=e($r['transaction_id']??'')?></small></td><td><span class="badge bg-light text-primary"><?=e($r['result_status']??'Pending')?></span><?php if($r['result_text']): ?><div class="small text-muted mt-1 report-snippet"><?=e(mb_strimwidth($r['result_text'],0,120,'...'))?></div><?php endif;?></td><td><?php if($r['report_id']): ?><button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#report<?=$r['id']?>"><i class="bi bi-file-earmark-text"></i> View</button><div class="modal fade" id="report<?=$r['id']?>" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h5><?=e($r['report_title'])?></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><p class="small text-muted"><?=e($r['test_name'])?> · <?=e($r['appointment_date'])?></p><div class="report-paper"><?=nl2br(e($r['report_content']))?></div></div></div></div></div><?php else: ?><span class="text-muted small">Not available</span><?php endif;?></td></tr><?php endforeach; if(!$rows):?><tr><td colspan="6"><div class="empty-state">No test history found.</div></td></tr><?php endif;?></tbody></table></div></div>
<?php require '../partials/footer.php'; ?>
